function icone(nome, classe = '') {
    const corpo = GAME_ICONS[nome];
    if (!corpo) return '';
    return `<svg viewBox="0 0 512 512" aria-hidden="true" class="inline-block ${classe}" style="width:1.15em;height:1.15em;vertical-align:-0.22em">${corpo}</svg>`;
}
